import{_ as t,o as a,a as o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"AI in Bagisto","description":"","frontmatter":{},"headers":[],"relativePath":"ai/introduction.md","filePath":"ai/introduction.md","lastUpdated":1789331268000}'),s={name:"ai/introduction.md"};function i(n,e,d,c,l,h){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="ai-in-bagisto" tabindex="-1">AI in Bagisto <a class="header-anchor" href="#ai-in-bagisto" aria-label="Permalink to &quot;AI in Bagisto&quot;">​</a></h1><p>Bagisto has <strong>generative AI built into the platform</strong>. Branded Magic AI, it writes, translates and draws for the merchant and the shopper on the AI provider of your choice, with nothing extra to install. Alongside it sit <strong>agentic AI</strong> hooks that let an AI agent act on the storefront, and tooling that makes the coding agents <em>you</em> build with fluent in Bagisto. Together they are Bagisto&#39;s path to <strong>agentic commerce</strong>, where an AI assistant can help run a store and an AI agent can shop it on someone&#39;s behalf. This page is the home for all of it.</p><div class="ai-cards__group-title">For your store</div><div class="ai-cards"><a class="ai-card" href="/ai/magic-ai.html"><div class="ai-card__title">✨ Generative AI (Magic AI)</div><div class="ai-card__desc"> Built-in generative AI for the store: product content &amp; images, image search, review translation and personalised checkout messages, on the AI provider of your choice. </div></a><a class="ai-card" href="/ai/webmcp.html"><div class="ai-card__title">🤖 WebMCP</div><div class="ai-card__desc"> Agentic AI on the storefront: tools declared for browser agents, so an agent can search, open a product, manage the wishlist and reach checkout on a shopper&#39;s behalf. </div></a></div><div class="ai-cards__group-title">For developers &amp; AI agents</div><div class="ai-cards"><a class="ai-card" href="/ai/agent-skills.html"><div class="ai-card__title">🧩 Agent Skills</div><div class="ai-card__desc"> Pre-built skills that teach AI coding agents (Claude Code, Cursor, Windsurf) Bagisto&#39;s conventions so they generate correct packages, payment methods and themes. </div></a><a class="ai-card" href="/ai/llms-txt.html"><div class="ai-card__title">📄 llms.txt</div><div class="ai-card__desc"> Context files that help LLMs and AI tools understand Bagisto&#39;s architecture for more accurate, framework-aware suggestions. </div></a></div><h2 id="three-kinds-of-ai-and-what-each-one-does" tabindex="-1">Three kinds of AI, and what each one does <a class="header-anchor" href="#three-kinds-of-ai-and-what-each-one-does" aria-label="Permalink to &quot;Three kinds of AI, and what each one does&quot;">​</a></h2><p>The terms are used deliberately, because they describe different things:</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning here</th><th>Where Bagisto has it today</th></tr></thead><tbody><tr><td><strong>Generative AI</strong></td><td>A model produces content: text, translations, keywords, images</td><td><a href="/ai/magic-ai.html">Magic AI</a>, in the core: product and page copy, product images, review translation, the keywords behind image search, the checkout message</td></tr><tr><td><strong>Agentic AI</strong></td><td>An AI agent performs actions through tools rather than only producing text</td><td><a href="/ai/webmcp.html">WebMCP</a>: seven storefront actions exposed to browser agents; <a href="/ai/agent-skills.html">Agent Skills</a>: coding agents that build Bagisto packages and themes</td></tr><tr><td><strong>Agentic commerce</strong></td><td>Commerce in which AI assists the merchant and can act for the shopper</td><td>The combination of the two above, in the core, with no separate product to install</td></tr></tbody></table><p>What Bagisto does <strong>not</strong> claim: Magic AI does not run your store on its own, and WebMCP does not complete a purchase without the shopper. Every generated text is applied by an admin, and every WebMCP tool ends in an ordinary storefront page where the person is still in charge.</p><h2 id="generative-ai-magic-ai-—-built-into-your-store" tabindex="-1">Generative AI (Magic AI) — built into your store <a class="header-anchor" href="#generative-ai-magic-ai-—-built-into-your-store" aria-label="Permalink to &quot;Generative AI (Magic AI) — built into your store&quot;">​</a></h2><p><a href="/ai/magic-ai.html">Generative AI</a> is a first-class Bagisto feature, shipped as the Magic AI package. Add an API key for any supported provider and you can:</p><ul><li>✍️ <strong>Generate content</strong> — product descriptions, page copy, and more from the admin editor.</li><li>🖼️ <strong>Generate images</strong> — create product imagery from a text prompt.</li><li>🔍 <strong>Image search</strong> — let shoppers search your catalog by uploading a photo.</li><li>🌐 <strong>Translate reviews</strong> — show customer reviews in the shopper&#39;s language.</li><li>🎉 <strong>Checkout messages</strong> — personalised order confirmation messages.</li></ul><p>It works with <strong>OpenAI, Anthropic, Gemini, Groq, xAI, DeepSeek, Mistral, and Ollama</strong>. Admin features let you choose which providers are offered; storefront features are configured per channel with a model each. Generated text and images are suggestions until an admin applies them.</p><h2 id="webmcp-—-agentic-ai-on-the-storefront" tabindex="-1">WebMCP — agentic AI on the storefront <a class="header-anchor" href="#webmcp-—-agentic-ai-on-the-storefront" aria-label="Permalink to &quot;WebMCP — agentic AI on the storefront&quot;">​</a></h2><p><a href="/ai/webmcp.html">WebMCP</a> is the browser-side counterpart. The storefront layout declares its search, product, wishlist, cart, checkout and newsletter actions as tools, and registers them with <code>navigator.modelContext.provideContext()</code> when the browser supports it. In every other browser the markup is inert. It is available on Bagisto 2.4 and 2.5 alike.</p><h2 id="ai-for-developers" tabindex="-1">AI for developers <a class="header-anchor" href="#ai-for-developers" aria-label="Permalink to &quot;AI for developers&quot;">​</a></h2><p>Bagisto also helps the AI tools <em>you</em> code with:</p><ul><li><strong><a href="/ai/agent-skills.html">Agent Skills</a></strong> — install <code>bagisto/agent-skills</code> so your AI agent generates Bagisto-correct packages, payment methods, themes, and tests.</li><li><strong><a href="/ai/llms-txt.html">llms.txt</a></strong> — point Copilot, Cursor, ChatGPT, or Claude at Bagisto&#39;s context files for architecture-aware answers.</li></ul><div class="tip custom-block"><p class="custom-block-title">Where to start</p><p>Building a store? Start with <strong><a href="/ai/magic-ai.html">Generative AI (Magic AI)</a></strong>. Letting agents shop it? Read <strong><a href="/ai/webmcp.html">WebMCP</a></strong>. Writing code? Install <strong><a href="/ai/agent-skills.html">Agent Skills</a></strong>.</p></div>',20)]))}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
